// Retrouve l'élément d'origine d'un item grâce au suivi des « paired items » de n8n
const origin = (node, i) => { try { return $(node).itemMatching(i)?.json; } catch (e) { return $(node).all()[i]?.json; } };

// Transforme la réponse France Travail en lignes prêtes pour la table `jobs`
const jobs = [];
const stats = [];
const seen = new Set();

$input.all().forEach((item, i) => {
  const search = origin('Recherches actives', i);
  if (!search?.id) return; // aucune recherche active
  const offres = Array.isArray(item.json.resultats) ? item.json.resultats : [];
  stats.push({ id: search.id, cnt: offres.length });

  for (const o of offres) {
    if (!o?.id || !o?.intitule || seen.has(o.id)) continue;
    seen.add(o.id);
    jobs.push({
      source: 'france_travail',
      external_id: String(o.id),
      url: o.origineOffre?.urlOrigine || `https://candidat.francetravail.fr/offres/recherche/detail/${o.id}`,
      title: o.intitule.trim(),
      company: o.entreprise?.nom || null,
      location: o.lieuTravail?.libelle || null,
      contract_type: o.typeContratLibelle || o.typeContrat || null,
      salary: o.salaire?.libelle || o.salaire?.commentaire || null,
      description: (o.description || '').slice(0, 8000),
      published_at: o.dateCreation || null,
      search_id: search.id,
      feed_id: null,
    });
  }
});

return [{ json: { origin: 'France Travail', jobs, search_stats: stats, feed_stats: [] } }];

// Retrouve l'élément d'origine d'un item grâce au suivi des « paired items » de n8n
const origin = (node, i) => { try { return $(node).itemMatching(i)?.json; } catch (e) { return $(node).all()[i]?.json; } };

// Garde les offres des 14 derniers jours et note l'état de santé de chaque flux
const since = Date.now() - 14 * 24 * 3600 * 1000;
const jobs = [];
const stats = new Map();
const seen = new Set();

$input.all().forEach((item, i) => {
  const feed = origin('Flux RSS actifs', i);
  if (!feed?.id) return; // aucun flux actif
  const s = stats.get(feed.id) ?? { id: feed.id, ok: true, error: null, cnt: 0 };
  stats.set(feed.id, s);

  const a = item.json;
  if (a.error) {
    s.ok = false;
    s.error = String(a.error.message ?? a.error).slice(0, 500);
    return;
  }
  if (!a.title || !a.link) return;
  const date = new Date(a.isoDate || a.pubDate || Date.now());
  if (Number.isNaN(date.getTime()) || date.getTime() < since) return;

  const externalId = String(a.guid || a.link);
  if (seen.has(externalId)) return;
  seen.add(externalId);

  // Beaucoup de flux utilisent le format « Entreprise: Intitulé du poste »
  let title = a.title.trim();
  let company = a.creator || null;
  const m = title.match(/^(.{2,80}?):\s+(.+)$/);
  if (m && !company) { company = m[1].trim(); title = m[2].trim(); }

  s.cnt++;
  jobs.push({
    source: 'rss',
    external_id: externalId,
    url: a.link,
    title,
    company,
    location: a.region || 'Remote',
    contract_type: null,
    salary: null,
    description: (a.contentSnippet || a.content || '').slice(0, 8000),
    published_at: date.toISOString(),
    search_id: null,
    feed_id: feed.id,
  });
});

return [{ json: { origin: 'RSS', jobs, search_stats: [], feed_stats: [...stats.values()] } }];
